 "content": "def transform(grid):
    """Turn the overlapping chain of 2x2 blocks into alternating colors."""
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    seen = set()
    objects = []
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 2 or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            cells = []
            while stack:
                y, x = stack.pop()
                cells.append((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    ny, nx = y + dy, x + dx
                    if 0 <= ny < h and 0 <= nx < w and (ny, nx) not in seen and grid[ny][nx] == 2:
                        seen.add((ny, nx))
                        stack.append((ny, nx))
            objects.append((min(x for y, x in cells), cells))

    # Components of one color that touch orthogonally belong to the same figure;
    # recolor alternating separate component groups from right to left.
    objects.sort(key=lambda obj: obj[0])
    for i, (_, cells) in enumerate(objects):
        color = 8 if i % 2 == 0 else 2
        for y, x in cells:
            out[y][x] = color
    return out
